import{_ as s,c as t,o as l,j as e,a as n}from"./chunks/framework.BKeRpnBD.js";const m=JSON.parse('{"title":"周易尚氏学简介","description":"周易尚氏学 - 周易尚氏学简介","frontmatter":{"title":"周易尚氏学简介","description":"周易尚氏学 - 周易尚氏学简介"},"headers":[],"relativePath":"zh/classics/shangshi/001.md","filePath":"zh/classics/shangshi/001.md"}'),r={name:"zh/classics/shangshi/001.md"};function i(c,a,o,p,d,h){return l(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易尚氏学简介",tabindex:"-1"},[n("周易尚氏学简介 "),e("a",{class:"header-anchor",href:"#周易尚氏学简介","aria-label":"Permalink to “周易尚氏学简介”"},"​")],-1),e("p",null,"注意",-1),e("p",null,"本站为扫描版，错字较多，请对比着看！！",-1),e("p",null,"《周易尚氏学》是由尚秉和先生所著，对《周易》进行深入研究和注释的学术著作。尚秉和，字节之，号滋溪老人、石烟道人，是河北行唐人，晚清进士，易学家。他博学多才，不仅精通易学，还擅长文学、中医、金石和绘画。尚秉和先生在易学领域造诣深厚，著述丰富，其中《周易尚氏学》和《周易古筮考》是他的代表作。",-1),e("p",null,"在《周易尚氏学》中，尚秉和先生继承了象数学的传统，认为《易经》的卦爻辞都是从卦象中派生出来的，因此他在书中重点通过卦象来解释《易经》。他强调，要理解《易经》，必须先了解卦爻辞是如何从卦象中产生的，这样卦象和卦辞才能相互关联。",-1),e("p",null,"该书对《易经》的卦象进行了归纳整理和推洐，提出了完整而详备的卦象说。同时，尚秉和先生广泛搜集了古人的筮案，并从学术角度进行了详细的考释。他还对《易经》中的象数进行了阐发，对筮法进行了研究，提出了解《易》的新思路。",-1),e("p",null,"《周易尚氏学》共有二十卷，内容涵盖了《周易》的上经、下经以及系辞上传、下传等部分，还包括了附录，如《周易古筮考》、《左传》《国语》易象释等，为易学爱好者和研究者提供了重要的文献参考价值。",-1),e("p",null,"尚秉和先生的这部作品，不仅在易学界产生了深远的影响，也为后来的学者提供了宝贵的研究资料和新的研究视角。通过他的努力，易学的研究得以进一步深化和发展。",-1)])])}const _=s(r,[["render",i]]);export{m as __pageData,_ as default};
